code.snippet:
body.t-swiss nav { border-bottom-width: 4px; }
body.t-swiss .logo { text-transform: uppercase; letter-spacing: 1px; }
body.t-swiss .logo span { display: inline-block; background: var(--accent); color: #fff; padding: 0 6px; margin-left: 4px; }
body.t-swiss .hero h1 { text-transform: none; font-weight: 800; }
body.t-swiss .section-title::before { content: ""; display: block; width: 46px; height: 10px; background: var(--accent); margin-bottom: 14px; }
body.t-swiss .section-tag { background: #111; color: #fff; border-color: #111; font-weight: 700; letter-spacing: 3px; }
body.t-swiss .card { border-width: 2px; }
body.t-swiss .card:hover { border-color: var(--accent); }
body.t-swiss .card.featured { border-color: var(--accent); border-width: 3px; }
body.t-swiss .card.featured::before { background: var(--accent); }
body.t-swiss .btn { border-width: 2px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }
body.t-swiss .btn-primary { background: var(--accent); color: #fff; }
body.t-swiss .btn-primary:hover { background: #111; }
body.t-swiss .btn-ghost:hover { border-color: var(--accent); color: var(--accent); }
body.t-swiss .bar-fill { background: #111; }
body.t-swiss .bar-row:first-child .bar-fill { background: var(--accent); }
body.t-swiss .bar-track { border: 2px solid #111; background: #fff; height: 12px; }
